1	const fs = require('fs/promises');
2	const { constants } = require('fs');
3	const path = require('path');
4	const yaml = require('yaml');
5	const portfinder = require('portfinder');
6	
7	const logger = require('../../../utils/logger');
8	const { DEFAULT } = require('./constants');
9	const { DEFAULT_KEY, CONFIG_KEYS, ADAPTERS_BY_CONFIG_KEY } = require('../adapters');
10	
11	const YAML_CONFIG = { singleQuote: true };
12	
13	/**
14	 * @description Configure Z2M container.
15	 * @param {string} basePathOnContainer - Zigbee2mqtt base path.
16	 * @param {object} config - Gladys Z2M stored configuration.
17	 * @param {boolean} setupMode - In setup mode.
18	 * @returns {Promise} Indicates if the configuration file has been created or modified.
19	 * @example
20	 * await this.configureContainer({});
21	 */
22	async function configureContainer(basePathOnContainer, config, setupMode = false) {
23	  logger.info('Z2M Docker container is being configured...');
24	
25	  // Create configuration path (if not exists)
26	  const configFilepath = path.join(basePathOnContainer, DEFAULT.CONFIGURATION_PATH);
27	  await fs.mkdir(path.dirname(configFilepath), {
28	    recursive: true,
29	  });
30	
31	  // Check if config file not already exists
32	  let configCreated = false;
33	  try {
34	    // eslint-disable-next-line no-bitwise
35	    await fs.access(configFilepath, constants.R_OK | constants.W_OK);
36	    logger.info('Z2M configuration file already exists.');
37	  } catch (e) {
38	    logger.info('Writing default Z2M configuration...');
39	    await fs.writeFile(configFilepath, yaml.stringify(DEFAULT.CONFIGURATION_CONTENT));
40	    configCreated = true;
41	  }
42	
43	  // Check for changes
44	  const fileContent = await fs.readFile(configFilepath);
45	  const loadedConfig = yaml.parse(fileContent.toString());
46	  const { mqtt = {} } = loadedConfig;
47	
48	  let configChanged = false;
49	  if (mqtt.user !== config.mqttUsername || mqtt.password !== config.mqttPassword) {
50	    mqtt.user = config.mqttUsername;
51	    mqtt.password = config.mqttPassword;
52	    loadedConfig.mqtt = mqtt;
53	    configChanged = true;
54	  }
55	
56	  // Setup adapter
57	  let adapterKey = Object.values(CONFIG_KEYS).find((configKey) =>
58	    ADAPTERS_BY_CONFIG_KEY[configKey].includes(config.z2mDongleName),
59	  );
60	  const { serial = {} } = loadedConfig;
61	
62	  // Set default adapter if not found
63	  adapterKey = adapterKey || DEFAULT_KEY;
64	
65	  if (serial.adapter !== adapterKey) {
66	    loadedConfig.serial.adapter = adapterKey;
67	    configChanged = true;
68	  }
69	
70	  // Setup TCP port
71	  const { frontend = {} } = loadedConfig;
72	  const { port } = frontend;
73	
74	  const existingPortConfig = !Number.isNaN(Number(port));
75	  const generateRandomPort =
76	    (setupMode || !existingPortConfig) && (config.z2mTcpPort === null || Number.isNaN(Number(config.z2mTcpPort)));
77	
78	  // Only if incoming port
79	  if (generateRandomPort) {
80	    // Set random port
81	    logger.debug('Generated random z2m port...');
82	    const { min, max, defaultPort } = DEFAULT.CONFIGURATION_PORTS;
83	    try {
84	      config.z2mTcpPort = await portfinder.getPortPromise({
85	        port: min,
86	        stopPort: max,
87	      });
88	    } catch (e) {
89	      logger.error('Unable to get a random port for zigbee2mqtt configuration', e);
90	      config.z2mTcpPort = defaultPort;
91	    }
92	  } else if (existingPortConfig) {
93	    // TCP Port is not found in config, but z2m is alrady configured
94	    // For upgrade Gladys mode
95	    logger.debug('Keep default z2m port...');
96	    config.z2mTcpPort = port;
97	  }
98	
99	  // Check for requested changes
100	  if (config.z2mTcpPort !== port) {
101	    loadedConfig.frontend = {
102	      port: Number(config.z2mTcpPort),
103	    };
104	    configChanged = true;
105	  }
106	
107	  if (configChanged) {
108	    logger.info('Writing custom zigbee2mqtt configuration file...');
109	    await fs.writeFile(configFilepath, yaml.stringify(loadedConfig, YAML_CONFIG));
110	  }
111	
112	  return configCreated || configChanged;
113	}
114	
115	module.exports = {
116	  configureContainer,
117	};
