17	async function installZ2mContainer(config, setupMode = false) {
18	  const { z2mDriverPath } = config;
19	  let creationNeeded = false;
20	
21	  let dockerContainers = await this.gladys.system.getContainers({
22	    all: true,
23	    filters: { name: [containerDescriptor.name] },
24	  });
25	  let [container] = dockerContainers;
26	
27	  /*
28	   * Manage case where Zigbee USB Dongle Path has changed by removing the container.
29	   * It will be created with good config later
30	   */
31	  if (dockerContainers.length > 0) {
32	    const containerDescription = await this.gladys.system.inspectContainer(container.id);
33	    if (containerDescription.HostConfig.Devices[0].PathOnHost !== z2mDriverPath) {
34	      logger.info(
35	        `Zigbee2mqtt container with USB dongle path ${containerDescription.HostConfig.Devices[0].PathOnHost} should be removed (new USB dongle path ${z2mDriverPath} configured)...`,
36	      );
37	      await this.gladys.system.stopContainer(container.id);
38	      await this.gladys.system.removeContainer(container.id);
39	      creationNeeded = true;
40	    }
41	  }
42	
43	  const { basePathOnContainer, basePathOnHost } = await this.gladys.system.getGladysBasePath();
44	  const containerPath = `${basePathOnHost}/zigbee2mqtt/z2m`;
45	  if (dockerContainers.length === 0 || creationNeeded) {
46	    // Restore backup only in case of new installation
47	    await this.restoreZ2mBackup(containerPath);
48	
49	    try {
50	      logger.info('Zigbee2mqtt is being installed as Docker container...');
51	      logger.info(`Pulling ${containerDescriptor.Image} image...`);
52	      await this.gladys.system.pull(containerDescriptor.Image);
53	
54	      logger.info(`Configuration of Device ${z2mDriverPath}`);
55	      const containerDescriptorToMutate = cloneDeep(containerDescriptor);
56	      containerDescriptorToMutate.HostConfig.Binds.push(`${containerPath}:/app/data`);
57	      containerDescriptorToMutate.HostConfig.Devices[0].PathOnHost = z2mDriverPath;
58	
59	      logger.info(`Creation of container...`);
60	      const containerLog = await this.gladys.system.createContainer(containerDescriptorToMutate);
61	      logger.trace(containerLog);
62	      logger.info('Zigbee2mqtt successfully installed and configured as Docker container');
63	      this.zigbee2mqttExist = true;
64	    } catch (e) {
65	      this.zigbee2mqttExist = false;
66	      logger.error('Zigbee2mqtt failed to install as Docker container:', e);
67	      throw e;
68	    } finally {
69	      this.emitStatusEvent();
70	    }
71	  }
72	
73	  const configChanged = await this.configureContainer(basePathOnContainer, config, setupMode);
74	
75	  try {
76	    dockerContainers = await this.gladys.system.getContainers({
77	      all: true,
78	      filters: { name: [containerDescriptor.name] },
79	    });
80	    [container] = dockerContainers;
81	
82	    // Check if we need to restart the container (container is not running / config changed)
83	    if (container.state !== 'running' || configChanged) {
84	      logger.info('Zigbee2mqtt container is (re)starting...');
85	      await this.gladys.system.restartContainer(container.id);
