// Matches ANSI color/escape sequences
// eslint-disable-next-line no-control-regex
const ANSI_COLOR_REGEX = /\x1B\[[0-9;]*[A-Za-z]/g;
// Matches remaining control characters
// eslint-disable-next-line no-control-regex
const CONTROL_CHARS_REGEX = /[\x00-\x1F\x7F]/g;

const EZSP_PROTOCOL_VERSION_ERROR_START = 'Adapter EZSP protocol version';
const EZSP_PROTOCOL_VERSION_ERROR_END = 'is not supported by Host';

const GENERIC_ERROR_REGEX = /error:/i;

const READ_LOGS_TIMEOUT_MS = 30 * 1000;

/**
 * @description Read Zigbee2mqtt container logs and detect fatal errors.
 * @param {string} containerId - Container id.
 * @returns {Promise} Resolve when the logs have been analysed.
 * @example
 * await this.readZ2mContainerLogs(container.id);
 */
async function readZ2mContainerLogs(containerId) {
  let lastErrorLine = null;
  let knownErrorFound = false;
  let errored = false;

  try {
    const stream = await this.gladys.system.getContainerLogs(containerId, { follow: true });

    await new Promise((resolve) => {
      let buffer = '';
      let done = false;
      let timeout = null;

      const finish = () => {
        if (done) {
          return;
        }
        done = true;
        if (timeout) {
          clearTimeout(timeout);
        }
        resolve();
      };

      const processLine = (rawLine) => {
        // Strip the Docker stream prefix byte, ANSI color codes and control characters
        const line = rawLine
          .slice(1)
          .replace(ANSI_COLOR_REGEX, '')
          .replace(CONTROL_CHARS_REGEX, '');

        // Known error: EZSP protocol version is not supported by the Zigbee2mqtt host
        if (line.includes(EZSP_PROTOCOL_VERSION_ERROR_START) && line.includes(EZSP_PROTOCOL_VERSION_ERROR_END)) {
          this.z2mContainerError = { code: 'EZSP_PROTOCOL_VERSION', message: null };
          knownErrorFound = true;
          if (stream && typeof stream.destroy === 'function') {
            stream.destroy();
          }
          finish();
          return;
        }

        // Generic error: keep the last matching line
        if (GENERIC_ERROR_REGEX.test(line)) {
          lastErrorLine = line.trim();
        }
      };

      timeout = setTimeout(finish, READ_LOGS_TIMEOUT_MS);

      stream.on('data', (chunk) => {
        if (done) {
          return;
        }
        buffer += chunk.toString();
        const lines = buffer.split('\n');
        buffer = lines.pop();
        lines.forEach((line) => {
          if (!done) {
            processLine(line);
          }
        });
      });

      stream.on('end', () => {
        if (!done && buffer.length > 0) {
          processLine(buffer);
        }
        finish();
      });

      stream.on('error', () => {
        errored = true;
        finish();
      });
    });
  } catch (e) {
    logger.debug('Unable to read Zigbee2mqtt container logs:', e);
    errored = true;
  }

  if (!knownErrorFound) {
    if (errored) {
      this.z2mContainerError = null;
    } else if (lastErrorLine !== null) {
      this.z2mContainerError = { code: null, message: lastErrorLine };
    } else {
      this.z2mContainerError = null;
    }
  }

  this.emitStatusEvent();
}

module.exports = {
  readZ2mContainerLogs,
};
